body.query:
query AccountBonds($address: String!) {
  Bond(where: { account: { _eq: $address } }, order_by: { createdAt: desc }) { id account adapter policyHash phase raised released undrawn principalRecovery revenueCollected stakeRecovery pool totalSupply effectiveCap defaulted triggered createdAt }
}

graphql:
query AccountEvidence($address: String!) {
  Issuer(where: { id: { _eq: $address } }) { id issuer tier project projectApproved activeBond grossRevenue toInvestors payments firstRevenueAt asset volume }
  DailyRevenue(where: { account: { _eq: $address } }, order_by: { day: asc }) { account day gross verified x402 }
  PayerTotal(where: { account: { _eq: $address } }, order_by: { amount: desc }) { account payer amount payments related reasons source }
}

query AccountBonds($address: String!) {
  Bond(where: { account: { _eq: $address } }, order_by: { createdAt: desc }) { id account adapter policyHash phase raised released undrawn principalRecovery revenueCollected stakeRecovery pool totalSupply effectiveCap defaulted triggered createdAt }
}
